177	// ---------------------------------------------------------------------------------------------
178	// Network helpers (ADR-0007: predicate on URL.pathname, real response + targeted change).
179	// ---------------------------------------------------------------------------------------------
180	
181	/** C3: country configuration with the UI texts. */
182	export const isCountryConfig = (code: string) => (url: URL) =>
183	  url.pathname === '/api/countries' &&
184	  url.searchParams.get('populate[0]') === 'wizardTexts' &&
185	  url.searchParams.get('filters[code][$eq]') === code;
186	
187	/** C4: form fields of a country. */
188	export const isFormFields = (code: string) => (url: URL) =>
189	  url.pathname === '/api/form-fields' &&
190	  url.searchParams.get('filters[country][code][$eq]') === code;
191	
192	/** C5: plans of a country. */
193	export const isPlans = (code: string) => (url: URL) =>
194	  url.pathname === '/api/plans' && url.searchParams.get('filters[country][code][$eq]') === code;
195	
196	/** C6: price factors of a country. */
197	export const isPriceFactors = (code: string) => (url: URL) =>
198	  url.pathname === '/api/countries' &&
199	  url.searchParams.get('populate[0]') === 'priceFactors' &&
200	  url.searchParams.get('filters[code][$eq]') === code;
201	
202	/** C7: terms and conditions of a country. */
203	export const isTerms = (code: string) => (url: URL) =>
204	  url.pathname === '/api/countries' &&
205	  url.searchParams.get('fields[1]') === 'termsAndConditions' &&
206	  url.searchParams.get('filters[code][$eq]') === code;
