227	/** Step 1 of Colombia filled with the seed-valid data of `CO.data` (fill / selectOption / check). */
228	export async function fillCoStep1(
229	  page: Page,
230	  overrides: Partial<Record<keyof typeof CO.data, string>> = {},
231	): Promise<void> {
232	  const d = { ...CO.data, ...overrides };
233	  const l = CO.labels;
234	  await page.getByLabel(l.documentType).selectOption(d.documentType);
235	  await page.getByLabel(l.documentNumber).fill(d.documentNumber);
236	  await page.getByLabel(l.birthDate).fill(d.birthDate);
237	  await page.getByLabel(l.city).selectOption(d.city);
238	  await page.getByLabel(l.dataConsent).check();
239	  await page.getByLabel(l.plate).fill(d.plate);
240	  await page.getByLabel(l.make).selectOption(d.make);
241	  await page.getByLabel(l.vehicleYear).fill(d.vehicleYear);
242	}
