244	export async function fillClStep1(page: Page): Promise<void> {
245	  const d = CL.data;
246	  const l = CL.labels;
247	  await page.getByLabel(l.rut).fill(d.rut);
248	  await page.getByLabel(l.birthDate).fill(d.birthDate);
249	  await page.getByLabel(l.city).selectOption(d.city);
250	  await page.getByLabel(l.dataConsent).check();
251	  await page.getByLabel(l.plate).fill(d.plate);
252	  await page.getByLabel(l.make).selectOption(d.make);
