256	/** `/co/form` → valid step 1 → `/co/plans`. */
257	export async function goToCoPlans(page: Page): Promise<void> {
258	  await page.goto('/co/form');
259	  await expect(heading(page)).toHaveText(CO.formTitle);
260	  await fillCoStep1(page);
261	  await page.getByRole('button', { name: CO.texts.continue }).click();
262	  await expect(page).toHaveURL(/\/co\/plans$/);
263	  await expect(heading(page)).toHaveText(CO.plansTitle);
264	}
265	
266	/** Radio of a plan, found by its accessible name (name + optional badge + price). */
267	export const planRadio = (page: Page, planName: string) =>
268	  page.getByRole('radio', { name: new RegExp(`^${planName}\\b`) });
269	
270	/** `/co/form` → plans → `planName` → `/co/summary`. */
271	export async function goToCoSummary(page: Page, planName: string = CO.recommended): Promise<void> {
272	  await goToCoPlans(page);
273	  await planRadio(page, planName).check();
274	  await page.getByRole('button', { name: CO.texts.continue }).click();
275	  await expect(page).toHaveURL(/\/co\/summary$/);
276	  await expect(heading(page)).toHaveText(CO.summaryTitle);
277	  // Plan and terms loaded (C5, C6 and C7 answered): the checkbox is enabled only then.
278	  await expect(page.locator('.summary-plan .final-price')).toBeVisible();
279	  await expect(page.getByRole('checkbox', { name: CO.texts.acceptTerms })).toBeEnabled();
280	}
281	
282	/** No horizontal scroll on the page (AC-01.28, AC-02.29, AC-03.35). */
283	export async function expectNoHorizontalScroll(page: Page): Promise<void> {
284	  const sizes = await page.evaluate(() => ({
285	    scrollWidth: document.documentElement.scrollWidth,
286	    clientWidth: document.documentElement.clientWidth,
287	  }));
288	  expect(sizes.scrollWidth, `scrollWidth ${sizes.scrollWidth} > clientWidth ${sizes.clientWidth}`).toBeLessThanOrEqual(
289	    sizes.clientWidth,
290	  );
291	}
292	
293	type Loc = ReturnType<Page['locator']>;
294	
295	/** Presses Tab once and checks that the focus lands on `target` (strict keyboard order). */
296	export async function tabTo(page: Page, target: Loc): Promise<void> {
297	  await page.keyboard.press('Tab');
298	  await expect(target).toBeFocused();
299	}
300	
301	/**
302	 * Leaves a native `<input type="date">` with Tab. Chrome gives the date input internal tab stops
303	 * (day / month / year segments), so Tab may stay on the same element; the next element reached
304	 * must still be `target` (no other control in between).
305	 */
306	export async function tabOutOfDate(page: Page, dateInput: Loc, target: Loc): Promise<void> {
307	  const dateId = await dateInput.getAttribute('id');
308	  for (let i = 0; i < 4; i++) {
309	    await page.keyboard.press('Tab');
310	    const activeId = await page.evaluate(() => document.activeElement?.id ?? '');
311	    if (activeId !== dateId) {
312	      break;
313	    }
314	  }
315	  await expect(target).toBeFocused();
316	}
