1	import {
2	  CO,
3	  NBSP,
4	  QUOTE_NUMBER_CO,
5	  expect,
6	  heading,
7	  planRadio,
8	  tabOutOfDate,
9	  tabTo,
10	  test,
11	} from '../../support/fixtures';
12	
13	/**
14	 * Full flow of Colombia required by the PDF ("at least one end-to-end test of the full flow"),
15	 * done with the keyboard only: no click, no fill, no selectOption. Covers the PDF scenarios
16	 * of the three stories plus the keyboard ACs (AC-01.27, AC-02.26, AC-03.33).
17	 */
18	test.describe('CO full flow (keyboard only)', () => {
19	  test('AC-01.1 AC-01.27 AC-01.32 AC-02.1 AC-02.2 AC-02.3 AC-02.8 AC-02.9 AC-02.26 AC-02.28 AC-03.1 AC-03.2 AC-03.3 AC-03.5 AC-03.8 AC-03.25 AC-03.27 AC-03.33 AC-03.34 CO form → plans → summary → terms → approved payment → confirmation', async ({
20	    page,
21	  }) => {
22	    const l = CO.labels;
23	    const d = CO.data;
24	
25	    // ---------------- Step 1 (US-01) ----------------
26	    await page.goto('/co');
27	    await expect(page).toHaveURL(/\/co\/form$/);
28	    // AC-01.27: focus on the step heading, step indicator marks step 1.
29	    await expect(heading(page)).toHaveText(CO.formTitle);
30	    await expect(heading(page)).toBeFocused();
31	    await expect(page.locator('[aria-current="step"]')).toContainText('Tus datos');
32	
33	    // AC-01.1: only the CO fields, in the configured order (sections policyholder, vehicle).
34	    const controls = page.locator('form input, form select');
35	    const ids = await controls.evaluateAll((els) => els.map((el) => el.id));
36	    expect(ids).toEqual([
37	      'f-co_documentType',
38	      'f-co_documentNumber',
39	      'f-co_birthDate',
40	      'f-co_city',
41	      'f-co_dataConsent',
42	      'f-co_plate',
43	      'f-co_make',
44	      'f-co_vehicleYear',
45	    ]);
46	
47	    // Keyboard: Tab through every control in order and fill it.
48	    await tabTo(page, page.getByLabel(l.documentType));
49	    await page.keyboard.press('ArrowDown'); // "" → cc
50	    await expect(page.getByLabel(l.documentType)).toHaveValue(d.documentType);
51	
52	    await tabTo(page, page.getByLabel(l.documentNumber));
53	    await page.keyboard.type(d.documentNumber);
54	
55	    await tabTo(page, page.getByLabel(l.birthDate));
56	    await page.keyboard.type('10052000'); // es-CO date input: dd mm yyyy
57	    await expect(page.getByLabel(l.birthDate)).toHaveValue(d.birthDate);
58	
59	    await tabOutOfDate(page, page.getByLabel(l.birthDate), page.getByLabel(l.city));
60	    await page.keyboard.press('ArrowDown'); // "" → bogota
61	    await expect(page.getByLabel(l.city)).toHaveValue(d.city);
62	
63	    await tabTo(page, page.getByLabel(l.dataConsent));
64	    await page.keyboard.press('Space');
65	    await expect(page.getByLabel(l.dataConsent)).toBeChecked();
66	
67	    await tabTo(page, page.getByLabel(l.plate));
68	    await page.keyboard.type(d.plate);
69	
70	    await tabTo(page, page.getByLabel(l.make));
71	    await page.keyboard.press('ArrowDown'); // "" → make_a
72	    await expect(page.getByLabel(l.make)).toHaveValue(d.make);
73	
74	    await tabTo(page, page.getByLabel(l.vehicleYear));
75	    await page.keyboard.type(d.vehicleYear);
76	
77	    // AC-01.32: continue (Tab to the button, Enter).
78	    await tabTo(page, page.getByRole('button', { name: CO.texts.continue }));
79	    await page.keyboard.press('Enter');
80	
81	    // ---------------- Step 2 (US-02) ----------------
82	    await expect(page).toHaveURL(/\/co\/plans$/);
83	    await expect(heading(page)).toHaveText(CO.plansTitle);
84	    await expect(heading(page)).toBeFocused(); // AC-02.28
85	    await expect(page.locator('[aria-current="step"]')).toContainText('Planes');
86	
87	    // AC-02.1: only active and published plans of CO, in the configured order.
88	    const radios = page.getByRole('radio');
89	    await expect(radios).toHaveCount(3);
90	    const names = await page.locator('.plan-name').allTextContents();
91	    expect(names.map((n) => n.trim())).toEqual([...CO.plans]);
92	    for (const hidden of CO.hiddenPlans) {
93	      await expect(page.getByText(hidden)).toHaveCount(0);
94	    }
95	
96	    // AC-02.2: the recommended plan is distinguished visually and textually.
97	    const recommendedCard = page.locator('.plan', { has: page.getByText(CO.recommended, { exact: true }) });
98	    await expect(recommendedCard).toHaveClass(/plan--recommended/);
99	    await expect(recommendedCard.locator('.badge')).toHaveText(CO.texts.recommended);
100	    await expect(page.locator('.badge')).toHaveCount(1);
101	
102	    // AC-02.8: COP without decimals, U+00A0 between "$" and the amount (exact string).
103	    const prices = (await page.locator('.plan-price').allTextContents()).map((p) => p.trim());
104	    expect(prices).toEqual(CO.plans.map((name) => CO.prices[name]));
105	    expect(prices[1]).toBe(`$${NBSP}1.320.000`);
106	
107	    // AC-02.26: Tab to the group, arrow to Plan Plus, Space, Tab to continue, Enter.
108	    await tabTo(page, planRadio(page, 'Plan Esencial'));
109	    await page.keyboard.press('ArrowDown');
110	    await expect(planRadio(page, 'Plan Plus')).toBeFocused();
111	    await page.keyboard.press('Space');
112	    // AC-02.3: marked as chosen.
113	    await expect(planRadio(page, 'Plan Plus')).toBeChecked();
114	    await expect(planRadio(page, 'Plan Esencial')).not.toBeChecked();
115	    await expect(recommendedCard).toHaveClass(/plan--selected/);
116	    await tabTo(page, page.getByRole('button', { name: CO.texts.back }));
117	    await tabTo(page, page.getByRole('button', { name: CO.texts.continue }));
118	    await page.keyboard.press('Enter');
119	
120	    // ---------------- Step 3 (US-03) ----------------
121	    await expect(page).toHaveURL(/\/co\/summary$/);
122	    await expect(heading(page)).toHaveText(CO.summaryTitle);
123	    await expect(heading(page)).toBeFocused(); // AC-03.34
124	    await expect(page.locator('[aria-current="step"]')).toContainText('Resumen y pago');
125	
126	    // AC-03.1: data of the policyholder, of the vehicle and the chosen plan with its final price.
127	    const data = page.locator('.summary-data');
128	    await expect(data.getByRole('heading', { name: 'Datos del asegurado' })).toBeVisible();
129	    await expect(data.getByRole('heading', { name: 'Datos del vehículo' })).toBeVisible();
130	    const items = await data.locator('.item').evaluateAll((els) =>
131	      els.map((el) => [
132	        el.querySelector('dt')?.textContent?.trim(),
133	        el.querySelector('dd')?.textContent?.trim(),
134	      ]),
135	    );
136	    expect(items).toEqual([
137	      [l.documentType, d.documentTypeLabel],
138	      [l.documentNumber, d.maskedDocument],
139	      [l.birthDate, '10 de mayo de 2000'],
140	      [l.city, d.cityLabel],
141	      [l.dataConsent, 'Sí'],
142	      [l.plate, d.plate],
143	      [l.make, d.makeLabel],
144	      [l.vehicleYear, '2018'],
145	    ]);
146	    const plan = page.locator('.summary-plan');
147	    await expect(plan.locator('.plan-name')).toHaveText(CO.recommended);
148	    await expect(plan.locator('.final-price strong')).toHaveText(`$${NBSP}1.320.000`);
149	
150	    // AC-03.5: document masked, type in clear, full value nowhere in the DOM.
151	    expect(await page.content()).not.toContain(d.documentNumber);
152	    const a11yTree = await page.locator('body').ariaSnapshot();
153	    expect(a11yTree).not.toContain(d.documentNumber);
154	
155	    // AC-03.2: terms of CO from Strapi; pay disabled until accepted.
156	    // The scrollable region (the enclosing <section> carries the same accessible name).
157	    const terms = page
158	      .getByRole('region', { name: 'Términos y condiciones' })
159	      .and(page.locator('[tabindex="0"]'));
160	    await expect(terms).toContainText(CO.texts.termsStart);
161	    const payButton = page.getByRole('button', { name: CO.texts.pay });
162	    await expect(payButton).toBeDisabled();
163	    // AC-03.34: disabled pay button described by the hint.
164	    await expect(payButton).toHaveAccessibleDescription(CO.texts.acceptTermsHint);
165	    const accept = page.getByRole('checkbox', { name: CO.texts.acceptTerms });
166	    await expect(accept).not.toBeChecked();
167	
168	    // AC-03.33: logical focus order — edit data, change plan, terms region, checkbox, outcome, pay.
169	    await tabTo(page, page.getByRole('button', { name: CO.texts.editData }));
170	    await tabTo(page, page.getByRole('button', { name: CO.texts.changePlan }));
171	    await tabTo(page, terms);
172	    // The terms region scrolls with the keyboard (it may not overflow at 1280 px; no error then).
173	    await page.keyboard.press('ArrowDown');
174	    await tabTo(page, accept);
175	    await page.keyboard.press('Space');
176	    await expect(accept).toBeChecked();
