3	/**
4	 * Shared fixtures (ADR-0007).
5	 *
6	 * - `page.clock.setFixedTime(FIXED_NOW)` before any navigation: `Date` is fixed, timers run
7	 *   normally (the 1500 ms of the payment are real).
8	 * - Network guard (AC-01.30, AC-02.31, AC-03.24): every request of the test is recorded and,
9	 *   at the end, every request must be a GET, no request may carry `Authorization`, and no request
10	 *   to the content API may ask for drafts (`status` / `publicationFilter`, AC-01.11).
11	 */
12	
13	/** 2026-11-22 12:00 in America/Bogota (UTC−5): the reference date of the specs. */
14	export const FIXED_NOW = new Date('2026-11-22T17:00:00.000Z');
15	
16	export interface RecordedRequest {
17	  readonly method: string;
18	  readonly url: URL;
19	  readonly request: Request;
20	}
21	
22	interface Fixtures {
23	  /** Every request made by the page during the test (filled by the auto fixture). */
24	  requests: RecordedRequest[];
25	  networkGuard: void;
26	}
27	
28	export const test = base.extend<Fixtures>({
29	  requests: async ({}, use) => {
30	    await use([]);
31	  },
32	  networkGuard: [
33	    async ({ page, requests }, use) => {
34	      page.on('request', (request) => {
35	        requests.push({ method: request.method(), url: new URL(request.url()), request });
36	      });
37	      await page.clock.setFixedTime(FIXED_NOW);
38	      await use();
39	
40	      const offenders: string[] = [];
41	      for (const { method, url, request } of requests) {
42	        if (url.protocol === 'data:' || url.protocol === 'blob:') {
43	          continue;
44	        }
45	        if (method !== 'GET') {
46	          offenders.push(`${method} ${url.pathname}`);
47	        }
48	        let headers: Record<string, string> = {};
49	        try {
50	          headers = await request.allHeaders();
51	        } catch {
52	          headers = request.headers();
53	        }
54	        if ('authorization' in headers) {
55	          offenders.push(`Authorization header on ${url.pathname}`);
56	        }
57	        if (url.pathname.startsWith('/api/')) {
58	          for (const key of url.searchParams.keys()) {
59	            if (key === 'status' || key.includes('publicationFilter')) {
60	              offenders.push(`draft parameter "${key}" on ${url.pathname}`);
61	            }
62	          }
63	        }
64	      }
65	      expect(offenders, 'AC-01.30 / AC-02.31 / AC-03.24 network guard').toEqual([]);
66	    },
67	    { auto: true },
68	  ],
69	});
