208	type Json = { data: unknown; meta?: unknown };
209	
210	/** Fetches the real response through nginx and fulfils it with `change(body)` applied. */
211	export async function modifyRealResponse(
212	  route: Route,
213	  change: (body: Json) => Json | void,
214	): Promise<void> {
215	  const response = await route.fetch();
216	  const body = (await response.json()) as Json;
217	  const changed = change(body) ?? body;
218	  await route.fulfill({ response, json: changed });
219	}
